This BFS marks vertices visited when they are dequeued instead of when they are enqueued. On a complete graph of 5 vertices, starting at 0, what happens?

```python
from collections import deque

def bfs(adj, s):
    queue, seen, dist = deque([(s, 0)]), set(), {}
    while queue:
        u, d = queue.popleft()
        if u in seen:
            continue
        seen.add(u)
        dist[u] = d
        for v in adj[u]:
            if v not in seen:
                queue.append((v, d + 1))
    return dist
```

This Dijkstra variant never relaxes edges into vertices it has already finalised. What does it print?

```python
import heapq

graph = {'S': [('A', 1), ('B', 5)], 'A': [('C', 1)],
         'B': [('A', -10)], 'C': []}

def dijkstra(g, s):
    dist = {v: float('inf') for v in g}
    dist[s], heap, done = 0, [(0, s)], set()
    while heap:
        d, u = heapq.heappop(heap)
        if u in done:
            continue
        done.add(u)
        for v, w in g[u]:
            if v not in done and d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(heap, (dist[v], v))
    return dist

print(dijkstra(graph, 'S')['C'])
```

This function is meant to detect a cycle in a directed graph. Which statements are true? (Choose two.)

```python
adj = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}
seen = set()

def has_cycle(u):
    seen.add(u)
    for v in adj[u]:
        if v in seen:
            return True
        if has_cycle(v):
            return True
    return False

print(has_cycle('A'))
```

