This attempt at "cheapest flight with at most k stops" uses Dijkstra and marks each city done the first time it is popped. With k = 1, from city 0 to city 3, what does it return?

```python
import heapq
from collections import defaultdict

flights = [[0, 1, 1], [0, 2, 5], [1, 2, 1], [2, 3, 1]]

def cheapest(flights, src, dst, k):
    g = defaultdict(list)
    for a, b, w in flights:
        g[a].append((b, w))
    heap, done = [(0, src, 0)], set()
    while heap:
        cost, u, used = heapq.heappop(heap)
        if u == dst:
            return cost
        if u in done:
            continue
        done.add(u)
        if used > k:
            continue
        for v, w in g[u]:
            heapq.heappush(heap, (cost + w, v, used + 1))
    return -1
```

This bipartite check is run on a graph whose edges are 0–1, 2–3, 3–4 and 4–2. What does it return?

```python
from collections import deque

def is_bipartite(adj):
    colour, queue = {0: 0}, deque([0])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in colour:
                colour[v] = 1 - colour[u]
                queue.append(v)
            elif colour[v] == colour[u]:
                return False
    return True
```
